-- 3) search_songs: exclude hidden/incomplete songs from fuzzy search
CREATE OR REPLACE FUNCTION search_songs(search_query text, result_limit int DEFAULT 50, min_similarity real DEFAULT 0.25)
RETURNS TABLE (
    id bigint,
    title text,
    slug text,
    image text,
    artist_id bigint,
    artist_name text,
    artist_is_active boolean
)
LANGUAGE sql
STABLE
SET search_path = public, extensions, pg_catalog
AS $$
    SELECT
        s.id, s.title, s.slug, s.image,
        a.id AS artist_id, a.name AS artist_name, a."isActive" AS artist_is_active
    FROM song s
    JOIN artist a ON a.id = s."artistId"
    WHERE (s.title ILIKE '%' || search_query || '%'
       OR similarity(s.title, search_query) > min_similarity)
      AND s."isActive" = true
    ORDER BY GREATEST(
        similarity(s.title, search_query),
        (s.title ILIKE '%' || search_query || '%')::int::real
    ) DESC
    LIMIT result_limit;
$$;

GRANT EXECUTE ON FUNCTION search_songs(text, int, real) TO anon, authenticated;

-- 4) get_top_songs: only count views for visible songs
CREATE OR REPLACE FUNCTION get_top_songs(limit_count int DEFAULT 5)
RETURNS TABLE (
  id int,
  title text,
  slug text,
  artist_name text,
  views bigint
)
LANGUAGE sql STABLE AS $$
  SELECT
    s.id,
    s.title,
    s.slug,
    a.name AS artist_name,
    COUNT(*)::bigint AS views
  FROM page_view pv
  JOIN song s ON s.id = pv."songId"
  JOIN artist a ON a.id = s."artistId"
  WHERE pv."songId" IS NOT NULL
    AND s."isActive" = true
  GROUP BY s.id, s.title, s.slug, a.name
  ORDER BY views DESC
  LIMIT limit_count;
$$;